import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]

    # For each x and right endpoint r, store the largest L among
    # constraints (L, R, x) with R <= r.
    max_left = [[0] * (n + 1) for _ in range(n + 1)]
    p = 2
    for _ in range(m):
        l, r, x = data[p], data[p + 1], data[p + 2]
        p += 3
        if l > max_left[x][r]:
            max_left[x][r] = l
    for x in range(1, n + 1):
        row = max_left[x]
        for r in range(1, n + 1):
            if row[r - 1] > row[r]:
                row[r] = row[r - 1]

    # Binomial coefficients for interleaving the left and right parts.
    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for a in range(n + 1):
        comb[a][0] = comb[a][a] = 1
        for b in range(1, a):
            comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

    # dp[l][r]: valid relative orderings on [l, r]. Empty intervals have one.
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for root in range(l, r + 1):
                # A constraint anchored at root lies wholly in [l,r], hence
                # root would be the maximum of that interval and is forbidden.
                if max_left[root][r] >= l:
                    continue
                ways = dp[l][root - 1] * dp[root + 1][r] % MOD
                total += ways * comb[length - 1][root - l]
            dp[l][r] = total % MOD

    print(dp[1][n])

if __name__ == '__main__':
    main()

