        if spf[p] == p:
            for k in range(p * p, m + 1, p):
                if spf[k] == k:
                    spf[k] = p
    nim_sum = 0
    for value in arr:
        omega = 0
        while value > 1:
            prime = spf[value]
            omega += 1
            value //= prime
        nim_sum ^= omega
    print('Anna' if nim_sum else 'Bruno')

