from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        # The two largest active left endpoints, counting duplicate pairs.
        top1_val = top1_id = top2_val = 0
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                if left >= top1_val:
                    top2_val = top1_val
                    top1_val, top1_id = left, idx
                elif left > top2_val:
                    top2_val = left

            # Valid left endpoints must be strictly greater than top1_val.
            total += right - top1_val

            # Removing the unique pair attaining the maximum relaxes this
            # right endpoint's limit from top1_val to top2_val.
            if top1_val > top2_val:
                gains[top1_id] += top1_val - top2_val

        return total + max(gains)

