                a, b = b, a
            by_right[b].append((a, idx))

        top1_val = top1_id = top2_val = 0
        gains = [0] * len(conflictingPairs)
        total = 0
        for r in range(1, n + 1):
            for val, idx in by_right[r]:
                if val >= top1_val:
                    top2_val = top1_val
                    top1_val, top1_id = val, idx
                elif val > top2_val:
                    top2_val = val
            total += r - top1_val
            if top1_val > top2_val:
                gains[top1_id] += top1_val - top2_val
        return total + max(gains, default=0)

