    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        size = min(n, x)
        dp = [0] * (size + 1)
        dp[0] = 1
        limit = 0

        for _ in range(n):
            new_limit = min(limit + 1, x)
            ndp = [0] * (size + 1)
            for k in range(new_limit + 1):
                if k <= limit:
                    ndp[k] += dp[k] * k
                if k > 0:
                    ndp[k] += dp[k - 1] * (x - k + 1) * y
                ndp[k] %= MOD
            dp = ndp
            limit = new_limit

        return sum(dp) % MOD

