class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        # Binomial coefficients modulo MOD.
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (n + 1)
        invfact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def choose(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        # ways[j] counts integers strictly less than s having j set bits.
        ways = [0] * (n + 1)
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                # First position where the candidate is smaller: use 0 here,
                # then choose the remaining set bits arbitrarily.
                for r in range(remaining + 1):
                    ways[prefix_ones + r] = (
                        ways[prefix_ones + r] + choose(remaining, r)
                    ) % MOD
                prefix_ones += 1

        answer = 0
        for weight in range(1, n + 1):
            # A number with this weight first maps to 'weight'.
            x = weight
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            if steps + 1 <= k:
                answer = (answer + ways[weight]) % MOD

        return answer

