import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    U = data[2::2]
    D = data[3::2]
    totals = [u + d for u, d in zip(U, D)]

    def feasible(h):
        lo = max(0, h - D[0])
        hi = min(U[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            cur_lo = max(0, h - D[i])
            cur_hi = min(U[i], h)
            lo = max(cur_lo, lo - x)
            hi = min(cur_hi, hi + x)
            if lo > hi:
                return False
        return True

    left, right = 0, min(totals) + 1
    while right - left > 1:
        mid = (left + right) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid

    print(sum(totals) - n * left)

if __name__ == '__main__':
    main()

