def fast(U,D,X):
 n=len(U); sums=[a+b for a,b in zip(U,D)]
 def ok(h):
  lo=max(0,h-D[0]);hi=min(U[0],h)
  if lo>hi:return False
  for i in range(1,n):
   a=max(0,h-D[i]);b=min(U[i],h)
   lo=max(a,lo-X);hi=min(b,hi+X)
   if lo>hi:return False
  return True
 h=max(h for h in range(min(sums)+1) if ok(h))
 return sum(sums)-len(U)*h

def brute(U,D,X):
 n=len(U); best=10**9
 for h in range(min(a+b for a,b in zip(U,D))+1):
  opts=[range(max(0,h-d),min(u,h)+1) for u,d in zip(U,D)]
  feasible=any(all(abs(v[i]-v[i+1])<=X for i in range(n-1)) for v in itertools.product(*opts))
