import sys, heapq

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    H,W,X=data[:3]
    P,Q=data[3]-1,data[4]-1
    a=data[5:]
    seen=bytearray(H*W)
    start=P*W+Q
    seen[start]=1
    strength=a[start]
    heap=[]
    def add(r,c):
        if 0<=r<H and 0<=c<W:
            k=r*W+c
            if not seen[k]:
                seen[k]=1
                heapq.heappush(heap,(a[k],k))
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        add(P+dr,Q+dc)
    while heap:
        val,k=heap[0]
        if val*X>=strength:
            break
        heapq.heappop(heap)
        strength+=val
        r,c=divmod(k,W)
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            add(r+dr,c+dc)
    print(strength)

if __name__=='__main__': main()

