import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    # The mountain/valley sequence is periodic modulo 2^61 for all
    # indices involved (the offsets are at most 10^18).
    period = 1 << 61
    limit = (1 << 100) - a[-1] - 1
    end = min(limit, period)
    best = 0
    for i in range(1, end + 1):
        score = 0
        for x in a:
            y = i + x
            if y:
                low = y & -y
                # Mountain exactly when the bit immediately above the
                # least significant set bit is zero.
                if (y & (low << 1)) == 0:
                    score += 1
        if score > best:
            best = score
    print(best)

if __name__ == '__main__':
    main()

