from itertools import combinations_with_replacement
from functools import lru_cache

def alg(a):
 n=len(a); i=0;j=(n+1)//2;ans=0
 while i<(n+1)//2 and j<n:
  if 2*a[i]<=a[j]:ans+=1;i+=1;j+=1
  else:j+=1
 return ans

def brute(a):
 @lru_cache(None)
 def f(mask):
  best=0
  i=next((i for i in range(len(a)) if not(mask>>i&1)),None)
  if i is None:return 0
  best=f(mask|1<<i)
  for j in range(i+1,len(a)):
   if not(mask>>j&1) and 2*a[i]<=a[j]:best=max(best,1+f(mask|1<<i|1<<j))
  return best
 return f(0)
for n in range(2,11):
 for a in combinations_with_replacement(range(1,7),n):
  if alg(a)!=brute(a): print('bad',a,alg(a),brute(a));raise SystemExit
print('ok')

