from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odd_total = (n + 1) // 2
        even_total = n // 2

        def completions(odd: int, even: int, first_odd: bool) -> int:
            remaining = odd + even
            need_odd = (remaining + 1) // 2 if first_odd else remaining // 2
            need_even = remaining - need_odd
            if odd != need_odd or even != need_even:
                return 0
            return fact[odd] * fact[even]

        total = sum(
            completions(
                odd_total - (x % 2),
                even_total - (1 - x % 2),
                x % 2 == 0,
            )
            for x in range(1, n + 1)
        )
        if k > total:
            return []

        unused = [True] * (n + 1)
        odd, even = odd_total, even_total
        previous_parity = None
        answer = []

        for _ in range(n):
            for x in range(1, n + 1):
                if not unused[x] or (
                    previous_parity is not None and x % 2 == previous_parity
                ):
                    continue

                remaining_odd = odd - (x % 2)
                remaining_even = even - (1 - x % 2)
                ways = completions(remaining_odd, remaining_even, x % 2 == 0)

                if k > ways:
                    k -= ways
                else:
                    answer.append(x)
                    unused[x] = False
                    odd, even = remaining_odd, remaining_even
                    previous_parity = x % 2
                    break

        return answer

