class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        # Choosing digit j in the first half contributes its value at
        # positions j and n-1-j (only once for the center position).
        coeff = []
        for j in range(m):
            mirror = n - 1 - j
            c = powers[j]
            if mirror != j:
                c += powers[mirror]
            coeff.append(c % k)

        # suffix[i] is a bitmask of all residues achievable by positions i..m-1.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            following = suffix[i + 1]
            mask = 0
            for r in range(k):
                if (following >> r) & 1:
                    for digit in range(10):
                        mask |= 1 << ((r + digit * coeff[i]) % k)
            suffix[i] = mask

        # Greedily maximize each digit, retaining only choices that can be
        # completed to a total residue of zero.
        half = []
        residue = 0
        for i, c in enumerate(coeff):
            first_digit = 1 if i == 0 else 0
            for digit in range(9, first_digit - 1, -1):
                new_residue = (residue + digit * c) % k
                needed = (-new_residue) % k
                if (suffix[i + 1] >> needed) & 1:
                    half.append(str(digit))
                    residue = new_residue
                    break

        half = ''.join(half)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

