class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); N=n
  nxt=[n]*n; st=[]
  for i in range(n-1,-1,-1):
   while st and nums[st[-1]]<=nums[i]: st.pop()
   nxt[i]=st[-1] if st else n
   st.append(i)
  LOG=n.bit_length()
  up=[nxt]
  sm=[[0]*n for _ in range(n)]
  for i in range(n): sm[0][i]=nums[i]*(nxt[i]-i)
  for j in range(1,LOG):
   prev=up[-1]; cur=[n]*n; arr=[0]*n; ps=sm[-1]
   for i in range(n):
    q=prev[i]
    if q<n:
     cur[i]=prev[q]; arr[i]=ps[i]+ps[q]
    else: arr[i]=ps[i]
   up.append(cur); sm.append(arr)
  pref=[0]
  for x in nums: pref.append(pref[-1]+x)
  def cost(l,r):
   p=l; total=0
   for j in range(LOG-1,-1,-1):
    q=up[j][p]
    if q<=r:
     total+=sm[j][p]; p=q
   total+=nums[p]*(r-p+1)
   return total-(pref[r+1]-pref[l])
  ans=0; left=0
  for r in range(n):
   lo=left; hi=r+1
   while lo<hi:
    mid=(lo+hi)//2
    if cost(mid,r)<=k: hi=mid
    else: lo=mid+1
   left=lo; ans+=r-left+1
  return ans

