def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    pos = 1
    ans = []
    for _ in range(t):
        H = int(data[pos]); W = int(data[pos + 1]); pos += 2
        grid = data[pos:pos + H]; pos += H

        row_prefix = [[0] * W for _ in range(H)]
        valid = True
        for i, row in enumerate(grid):
            cur = 0
            for j, c in enumerate(row):
                row_prefix[i][j] = cur
                cur ^= (c == 65)
            if cur:
                valid = False

        col_prefix = [[0] * W for _ in range(H)]
        for j in range(W):
            cur = 0
            for i in range(H):
                col_prefix[i][j] = cur
                cur ^= (grid[i][j] == 65)
            if cur:
                valid = False

        if not valid:
            ans.append('0')
            continue

        n = H + W
        parent = list(range(n))
        size = [1] * n
        parity = [0] * n  # value[node] xor value[parent[node]]

        def find(x):
            if parent[x] != x:
                p = parent[x]
                parent[x] = find(p)
                parity[x] ^= parity[p]
            return parent[x]

        def unite(a, b, wanted):
            ra = find(a); xa = parity[a]
            rb = find(b); xb = parity[b]
            if ra == rb:
                return (xa ^ xb) == wanted
            link_parity = xa ^ xb ^ wanted
            if size[ra] < size[rb]:
                parent[ra] = rb
                parity[ra] = link_parity
                size[rb] += size[ra]
            else:
                parent[rb] = ra
                parity[rb] = link_parity
                size[ra] += size[rb]
            return True

        ok = True
        for i, row in enumerate(grid):
            for j, c in enumerate(row):
                if c == 66:
                    # row_seed xor col_seed = 1 xor horizontal_prefix xor vertical_prefix
                    if not unite(i, H + j, 1 ^ row_prefix[i][j] ^ col_prefix[i][j]):
                        ok = False

        if not ok:
            ans.append('0')
        else:
            components = sum(find(i) == i for i in range(n))
            ans.append(str(pow(2, components, MOD)))

    sys.stdout.write('\n'.join(ans))

