from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        segs = [part for part in p.split('*') if part]
        if not segs:
            return 0

        n = len(s)

        def occurrences(pattern):
            m = len(pattern)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            found = []
            j = 0
            for i, char in enumerate(s):
                while j and char != pattern[j]:
                    j = prefix[j - 1]
                if char == pattern[j]:
                    j += 1
                if j == m:
                    found.append(i - m + 1)
                    j = prefix[j - 1]
            return found

        positions = [occurrences(part) for part in segs]
        if any(not found for found in positions):
            return -1

        lengths = [len(part) for part in segs]
        answer = n + 1
        # For each occurrence of the first literal, greedily use the earliest
        # non-overlapping occurrence of every following literal.
        for start in positions[0]:
            end = start + lengths[0]
            for k in range(1, len(segs)):
                idx = bisect_left(positions[k], end)
                if idx == len(positions[k]):
                    break
                end = positions[k][idx] + lengths[k]
            else:
                answer = min(answer, end - start)

        return -1 if answer == n + 1 else answer

