    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        segs = [x for x in parts if x]
        if not segs:
            return 0
        n = len(s)
        def occurrences(t):
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j-1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
