from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Generate the shared DFS string in postorder without recursion.
        order = []
        stack = [(0, False)]
        while stack:
            node, visited = stack.pop()
            if visited:
                order.append(node)
            else:
                stack.append((node, True))
                # Children were appended in increasing order; reverse the push
                # order so they are processed in increasing order.
                for child in reversed(children[node]):
                    stack.append((child, False))

        text = ''.join(s[node] for node in order)
        size = [1] * n
        position = [0] * n
        for i, node in enumerate(order):
            position[node] = i
            if parent[node] != -1:
                size[parent[node]] += size[node]

        # Manacher radii for odd- and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for node in range(n):
            end = position[node]
            length = size[node]
            start = end - length + 1
            if length % 2:
                center = (start + end) // 2
                answer[node] = odd[center] >= length // 2 + 1
            else:
                center = (start + end + 1) // 2
                answer[node] = even[center] >= length // 2
        return answer

