    def maxScore(self, nums: List[int]) -> int:
        def score(arr: List[int]) -> int:
            if not arr:
                return 0
            g = l = arr[0]
            for x in arr[1:]:
                g = gcd(g, x)
                l = l // gcd(l, x) * x
            return g * l

