class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        freq = [0] * 26
        for ch in s:
            freq[ord(ch) - ord('a')] += 1

        # dp[c] is the length produced by one occurrence of c
        # after the current number of transformations.
        dp = [1] * 26
        for _ in range(t):
            nxt = [0] * 26
            for c in range(25):
                nxt[c] = dp[c + 1]
            nxt[25] = (dp[0] + dp[1]) % mod
            dp = nxt

        return sum(freq[c] * dp[c] for c in range(26)) % mod

