class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        prime = bytearray(b'\x01') * 10000
        prime[0:2] = b'\x00\x00'
        for p in range(2, 100):
            if prime[p]:
                count = (9999 - p * p) // p + 1
                prime[p * p:10000:p] = b'\x00' * count

        if prime[n] or prime[m]:
            return -1

        digits = len(str(n))
        lower = 10 ** (digits - 1)
        upper = 10 ** digits
        distances = {n: n}
        queue = [(n, n)]

        while queue:
            cost, value = heapq.heappop(queue)
            if cost != distances.get(value):
                continue
            if value == m:
                return cost

            place = 1
            while place < upper:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distances.get(nxt, float('inf')):
                            distances[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if nxt >= lower and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distances.get(nxt, float('inf')):
                            distances[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))
                place *= 10

        return -1

