from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0

        # Z[i] is the common-prefix length of nums and nums[i:].
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        # d is the length of nums2; i is its starting index.
        for d in range(1, n):
            # run[i] is the common-prefix length of nums[i:] and nums[i+d:].
            run = [0] * (n - d + 1)
            for i in range(n - d - 1, 0, -1):
                if nums[i] == nums[i + d]:
                    run[i] = run[i + 1] + 1

            for i in range(1, n - d):
                # The first condition also requires nums2 to be at least as
                # long as nums1; the second compares nums2 directly to nums3.
                first_condition = d >= i and z[i] >= i
                second_condition = run[i] >= d
                if first_condition or second_condition:
                    answer += 1

        return answer

