from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)

        is_target = [False] * n
        for i in targetIndices:
            is_target[i] = True

        inf = n + 1
        # dp[j] is the minimum number of target indices used to match
        # pattern[:j] using the portion of source processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = int(is_target[i])
            # Descending order ensures each source character is used at most once.
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] < inf:
                    dp[j + 1] = min(dp[j + 1], dp[j] + cost)

        return len(targetIndices) - dp[m]

