class Solution:
    def minCost(self, n: int, cost: list[list[int]]) -> int:
        # A state (a, b) assigns colors to the current mirrored pair:
        # a to the left house and b to the right house.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]

        # Minimum cost after painting the outermost pair.
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Add mirrored pairs, moving inward.
        for i in range(1, n // 2):
            ndp = [0] * len(states)
            for x, (a, b) in enumerate(states):
                best_previous = min(
                    dp[y]
                    for y, (prev_left, prev_right) in enumerate(states)
                    if prev_left != a and prev_right != b
                )
                ndp[x] = cost[i][a] + cost[n - 1 - i][b] + best_previous
            dp = ndp

        return min(dp)

