class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # The augmented endpoints make every relevant zero run bounded by ones.
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0
        # Removing an internal run of ones merges its neighboring zero runs.
        # Flipping the merged run adds exactly the number of zeros it contained,
        # offset by the ones removed, so the net gain is the two zero-run lengths.
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                best_gain = max(best_gain, runs[k - 1][1] + runs[k + 1][1])

        return s.count('1') + best_gain

