class Solution:
    def calculateScore(self, s: str) -> int:
        # Each stack contains unmatched indices for one letter.
        stacks = [[] for _ in range(26)]
        score = 0

        for i, ch in enumerate(s):
            letter = ord(ch) - ord('a')
            mirror = 25 - letter
            if stacks[mirror]:
                # The most recent unmatched mirror is the closest valid index.
                j = stacks[mirror].pop()
                score += i - j
            else:
                stacks[letter].append(i)

        return score

