from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {(x, y) for x, y in points}
        xs = sorted({x for x, y in points})
        ys = sorted({y for x, y in points})
        best = -1

        for i, x1 in enumerate(xs):
            for x2 in xs[i + 1:]:
                for j, y1 in enumerate(ys):
                    for y2 in ys[j + 1:]:
                        corners = ((x1, y1), (x1, y2), (x2, y1), (x2, y2))
                        if not all(corner in point_set for corner in corners):
                            continue

                        # Any point other than these corners in the closed rectangle
                        # invalidates the candidate.
                        if any(
                            x1 <= x <= x2 and y1 <= y <= y2
                            and (x, y) not in corners
                            for x, y in points
                        ):
                            continue

                        best = max(best, (x2 - x1) * (y2 - y1))

        return best

